import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            p = []
            for _ in range(n):
                p.append(int(next(iterator)))
        except StopIteration:
            break

        p_prime = [0] * n
        for i in range(n):
            p_prime[i] = p[n - 1 - i]

        if p_prime == p:
            for i in range(n - 1):
                if p[i] != p[i+1]:
                    p_prime[i], p_prime[i+1] = p[i+1], p[i]
                    break
            else:
                pass

        results.append(" ".join(map(str, p_prime)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
